// Display records generated by the downloadable OneSimulation model.
async function showSampledLoop(panel) {
  const response = await fetch("/assets/sampled-feedback.json");
  if (!response.ok) return;
  const runs = await response.json();
  const slider = panel.querySelector("input");
  const report = panel.querySelector("output");
  const body = panel.querySelector("tbody");

  function display() {
    const period = Number(slider.value);
    const run = runs.find(entry => Math.abs(entry.period - period) < 1e-6);
    const pole = (run.outputs[2] - run.outputs[1]) / (run.outputs[1] - run.outputs[0]);
    report.textContent = "Sample interval " + period.toFixed(2) + " s. Measured pole " + pole.toFixed(4) + ".";
    body.replaceChildren();
    run.outputs.forEach((value, n) => {
      const row = body.insertRow();
      const step = document.createElement("th");
      step.scope = "row";
      step.textContent = n;
      row.append(step);
      row.insertCell().textContent = (period * n).toFixed(2);
      row.insertCell().textContent = value.toFixed(5);
    });
  }
  slider.addEventListener("input", display);
  display();
  panel.hidden = false;
}
for (const panel of document.querySelectorAll("[data-sampled-loop]")) {
  // The derivation, reference figure and runnable model are available offline in the notes.
  showSampledLoop(panel).catch(() => {});
}
